SELECT * FROM ( SELECT ROWNUM AS rn, A.* FROM ( SELECT N.NOTICE_NUMBER AS noticeNumber, NULL AS noticeCode, N.NOTICE_TITLE AS noticeTitle, N.NOTICE_CONTENT AS noticeContent, N.NOTICE__DATE AS noticeDate, NVL(N.VIEWS, 0) AS views, N.NOTICE_CATEGORY AS noticeCategory, N.NOTICE_AUTHOR AS employeeCode FROM ADMIN_NOTICE N
AND ( N.NOTICE_TITLE LIKE '%' || #{keyword} || '%' OR DBMS_LOB.INSTR(N.NOTICE_CONTENT, #{keyword}) > 0 )
AND N.NOTICE_CATEGORY = #{category}
ORDER BY N.NOTICE_NUMBER DESC ) A WHERE ROWNUM <= #{endRow} ) WHERE rn >= #{startRow}

SELECT COUNT(*) FROM ADMIN_NOTICE N
AND ( N.NOTICE_TITLE LIKE '%' || #{keyword} || '%' OR DBMS_LOB.INSTR(N.NOTICE_CONTENT, #{keyword}) > 0 )
AND N.NOTICE_CATEGORY = #{category}

